      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and opened exceptionally sensitive tests of fundamental physics through comparisons of atomic transition frequencies.",
        "attribution": "Katori and Ye made complementary, independently developed advances in trapping atoms and realizing highly accurate optical clocks.",
        "maturity": "The method has been replicated and refined across laboratories, with clock performance and applications continuing to advance.",
        "uncertainties": [
          "The wider clock community has made substantial contributions to later performance and applications."
        ]
      }
    },
